 async function api(path,method='GET',data){const r=await fetch(path,{method,headers:{'X-Bilal-Request':'1',...(data!==undefined?{'Content-Type':'application/json'}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});let b;try{b=await r.json();}catch(_){throw Error('Der Server antwortet nicht wie erwartet. Bitte Verbindung und Einrichtung prüfen.');}if(!r.ok){const e=Error(b.error||'Anfrage fehlgeschlagen.');e.status=r.status;throw e;}return b;}
 function toast(text,error=false){const node=$('#toast');node.textContent=text;node.className='toast visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.className='toast',5000);}
 function fail(e){toast(e.message||String(e),true);$('#saveStatus').textContent='Bitte prüfen';$('#saveStatus').className='save-status warning';}
 function download(filename,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportState(value=state){download('Bilal-Schule-Sicherung-'+today()+'.json',JSON.stringify({...value,version:39,createdAt:new Date().toISOString()},null,2));}
 async function save(change){
  if(busy)throw Error('Ein Speichervorgang läuft bereits.');if(!user||user.role!=='admin')throw Error('Keine Administratorrechte.');
  busy=true;$('#saveStatus').textContent='Wird gespeichert …';$('#saveStatus').className='save-status saving';
  const next=E(state);try{change(next);const result=await api('/api/legacy','PUT',next);next.revision=result.revision;state=next;pending=null;$('#recovery').hidden=true;$('#saveStatus').textContent='Gespeichert';$('#saveStatus').className='save-status';toast('Änderungen gespeichert.');return true;}
  catch(e){pending=next;$('#recovery').hidden=false;fail(e);throw e;}
  finally{busy=false;}
 }
 async function load(){
  const status=await api('/api/status');if(!status.user){showLogin(status.needsSetup);return;}
  user=status.user;
  if(user.role==='admin'){state=await api('/api/legacy');admin=await api('/api/admin');portal=await api('/api/portal');}
  else{portal=await api('/api/portal');state={members:portal.members,db:{classes:portal.classes},brand:portal.brand};}
  $('#loading').hidden=true;$('#auth').hidden=true;$('#workspace').hidden=false;$('#accountName').textContent=user.name||user.username;$('#accountRole').textContent=roleLabels[user.role]||user.role;applyBrand();renderNav();render();
 }
 function showLogin(setup=false){
  $('#loading').hidden=true;$('#workspace').hidden=true;$('#auth').hidden=false;
  $('#authTitle').textContent=setup?'Administrator einrichten':'Willkommen zurück';
  $('#authDescription').textContent=setup?'Lege deinen persönlichen Zugang zur Schulverwaltung an.':'Melde dich mit deinem Benutzerkonto an.';
  $('#authSubmit').textContent=setup?'Administratorkonto erstellen':'Anmelden';
  $('#authForm').onsubmit=async e=>{e.preventDefault();const b=new FormData(e.target),button=$('#authSubmit');button.disabled=true;$('#authError').textContent='';try{await api(setup?'/api/setup':'/api/login','POST',{username:b.get('username'),password:b.get('password'),name:b.get('username')});await load();}catch(err){$('#authError').textContent=err.message;}finally{button.disabled=false;}};
 }
 function applyBrand(){const b=state.brand||{};$('#schoolName').textContent=b.name||'Bilal-Schule';$('#schoolMotto').textContent=b.motto||'Wissen. Werte. Gemeinschaft.';const logo=/^data:image\/(png|jpeg|webp);base64,/.test(b.logoData||'')?b.logoData:'/bilal-logo.png';$('#schoolLogo').src=logo;for(const [key,value]of [['--green',b.navy],['--gold',b.gold],['--background',b.bg]])if(/^#[a-f\d]{6}$/i.test(value||''))document.documentElement.style.setProperty(key,value);}
