 function pill(value){const bad=/offen|fehlt|überfällig|inaktiv/i.test(value||'');return '<span class="pill '+(bad?'amber':'')+'">'+esc(value||'–')+'</span>';}
 function action(label,act,extra='',primary=false){return '<button type="button" class="'+(primary?'button primary':'button')+'" data-action="'+act+'" '+extra+'>'+label+'</button>';}
