 function classes(){const rows=filtered(state.db.classes||[]);return rows.length?'<div class="class-grid">'+rows.map(c=>{const n=state.members.filter(m=>m.group===c.name).length,limit=Number(c.capacity)||0;return '<article class="class-card"><div class="class-card-top"><span class="class-letter">'+esc(c.name.slice(0,1))+'</span>'+pill(limit&&n>limit?'Über Kapazität':n+' Schüler')+'</div><h3>'+esc(c.name)+'</h3><p>'+esc(c.teacher||'Lehrkraft noch offen')+'</p><dl><div><dt>Unterricht</dt><dd>'+esc([c.days,c.time].filter(Boolean).join(' · ')||'Noch nicht geplant')+'</dd></div><div><dt>Raum</dt><dd>'+esc(c.room||'Noch nicht zugeteilt')+'</dd></div></dl><div class="capacity-track"><i style="width:'+Math.min(100,limit?n/limit*100:0)+'%"></i></div><small>'+n+(limit?' von '+limit+' Plätzen':' Schüler zugeordnet')+'</small><div class="class-card-bottom"><button class="button primary" data-class="'+c.id+'">Schüler verwalten '+icon('arrow')+'</button>'+(user.role==='admin'?editAction('classes',c.id):'')+(user.role==='admin'?'<button class="text-action danger" data-delete-class="'+c.id+'">Löschen</button>':'')+'</div></article>';}).join('')+'</div>':empty('Bereit für die erste Klasse','Klicke auf „Klasse hinzufügen“. Lehrkraft, Raum und Schüler lassen sich anschließend zuordnen.');}
